	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void retainedUnionKeepsEarlierJoinEntryWithThreeOperands(boolean unionLast) {
		String gate = "?g1 <urn:gate1> ?g2 .";
		if (!unionLast) {
			gate += " ?g2 <urn:gate2> ?g3 . ?g3 <urn:gate3> ?g4 . ?g4 <urn:gate4> ?g5 .";
		}
		String query = """
				SELECT ?end ?v1 ?v2 WHERE {
				  VALUES ?outer { 1 }
				  OPTIONAL {
				    SELECT DISTINCT ?end ?v1 ?v2 WHERE {
				      {
				        ?end <urn:wide1> ?v1 .
				        ?other1 <urn:rare1> <urn:w1> .
				        ?v1 <urn:inside>+ ?u1 .
				      }
				      UNION
				      {
				        ?end <urn:wide2> ?v2 .
				        ?other2 <urn:rare2> <urn:w2> .
				        ?v2 <urn:inside>+ ?u2 .
				      }
				      <urn:start> <urn:step>+ ?end .
				      { %s }
				    }
				  }
				}
				""".formatted(gate);
		List<Statement> data = List.of(
				statement("start", "step", "endValue"),
				statement("endValue", "wide1", "value1"),
				statement("other1", "rare1", "w1"),
				statement("value1", "inside", "tail1"),
				statement("endValue", "wide2", "value2"),
				statement("other2", "rare2", "w2"),
				statement("value2", "inside", "tail2"),
				statement("gateA", "gate1", "gateB"),
				statement("gateB", "gate2", "gateC"),
				statement("gateC", "gate3", "gateD"),
				statement("gateD", "gate4", "gateE"));
		List<BindingSet> expected = List.of(row("end", "endValue", "v1", "value1"),
				row("end", "endValue", "v2", "value2"));
		assertThat(evaluate(parse(query), new RecordingStrategy(new RecordingTripleSource(data))))
				.containsExactlyInAnyOrderElementsOf(expected);

		RecordingTripleSource source = new RecordingTripleSource(data);
		RecordingStrategy strategy = new RecordingStrategy(source);
		TupleExpr optimized = strategy.optimize(parse(query), new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		Union union = onlyUnion(optimized);
		List<BindingSet> actual = evaluate(optimized, strategy);

		assertAll(
				() -> assertThat(actual).containsExactlyInAnyOrderElementsOf(expected),
				() -> assertThat(union.isVariableScopeChange()).isTrue(),
				() -> {
					assertThat(union.getParentNode()).isInstanceOf(Join.class);
					Join containingJoin = (Join) union.getParentNode();
					assertThat(unionLast ? containingJoin.getRightArg() : containingJoin.getLeftArg())
							.as("the retained UNION's position inside the final three-operand hierarchy")
							.isSameAs(union);
					assertThat(containingJoin.getParentNode()).isInstanceOf(Join.class);
					Join outerJoin = (Join) containingJoin.getParentNode();
					assertThat(outerJoin.getLeftArg()).isInstanceOf(ArbitraryLengthPath.class);
					assertThat(outerJoin.getRightArg()).isSameAs(containingJoin);
				},
				() -> assertThat(strategy.inputs.get(union)).isNotEmpty().allSatisfy(input -> {
					assertThat(input.getValue("end"))
							.as("the earlier path is an invocation input of the UNION's containing join")
							.isEqualTo(iri("endValue"));
					assertThat(input.getBindingNames()).doesNotContain("g1", "g2", "g3", "g4", "g5");
				}),
				() -> assertPatternFirst(union.getLeftArg(), "wide1", "rare1"),
				() -> assertPatternFirst(union.getRightArg(), "wide2", "rare2"),
				() -> assertEndpointLookupFirst(source, "wide1", "rare1"),
				() -> assertEndpointLookupFirst(source, "wide2", "rare2"));
	}

	@Test
	void nestedOptionalMustNotAcquireAReorderedUnionEntryBinding() {
		StatementPattern optionalPattern = new StatementPattern(Var.of("x"),
				Var.of("optionalPredicate", iri("optional"), true, true),
				Var.of("optionalObject", iri("object"), true, true));
		optionalPattern.setVariableScopeChange(true);
		Union union = new Union(
				new Extension(new LeftJoin(new SingletonSet(), optionalPattern),
						new ExtensionElem(new ValueConstant(iri("optionalBranch")), "branch")),
				new Extension(new SingletonSet(),
						new ExtensionElem(new ValueConstant(iri("independentBranch")), "branch")));
		union.setVariableScopeChange(true);
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("x"));
		values.setBindingSets(List.of(row("x", "incoming")));
		StatementPattern gate = new StatementPattern(Var.of("gate"),
				Var.of("gatePredicate", iri("gatePredicate"), true, true),
				Var.of("gateObject", iri("gateObject"), true, true));
		QueryRoot original = new QueryRoot(new Join(union, new Join(values, gate)));
		List<Statement> data = List.of(statement("matched", "optional", "object"),
				statement("gateValue", "gatePredicate", "gateObject"));
		BindingSet expected = row("x", "incoming", "branch", "independentBranch", "gate", "gateValue");
		assertThat(evaluate(original.clone(), new RecordingStrategy(new RecordingTripleSource(data))))
				.containsExactly(expected);

		// VALUES is cheapest, but putting it before the containing join makes x an invocation input of the
		// retained UNION. The scoped OPTIONAL then loses its incompatible local match and emits an unmatched
		// left row instead. Its unrelated branch-local BIND does not describe this input sensitivity.
		QueryRoot unsafeOrder = new QueryRoot(new Join(values.clone(), new Join(union.clone(), gate.clone())));
		assertThat(evaluate(unsafeOrder, new RecordingStrategy(new RecordingTripleSource(data))))
				.containsExactlyInAnyOrder(expected,
						row("x", "incoming", "branch", "optionalBranch", "gate", "gateValue"));

		QueryRoot optimized = original.clone();
		RecordingTripleSource source = new RecordingTripleSource(data);
		new QueryJoinOptimizer(new EvaluationStatistics(), source)
				.optimize(optimized, null, EmptyBindingSet.getInstance());
		RecordingStrategy strategy = new RecordingStrategy(source);
		Union optimizedUnion = onlyUnion(optimized);
		List<BindingSet> actual = evaluate(optimized, strategy);

		assertAll(
				() -> assertThat(actual).containsExactly(expected),
				() -> assertThat(optimizedUnion.isVariableScopeChange()).isTrue(),
				() -> assertThat(strategy.inputs.get(optimizedUnion)).isNotEmpty()
						.allSatisfy(input -> assertThat(input.hasBinding("x"))
								.as("nested OPTIONAL observations constrain reordering of the containing UNION")
								.isFalse()));
	}

	private static void assertPatternFirst(TupleExpr branch, String expectedFirst, String otherPredicate) {
		List<StatementPattern> statements = new ArrayList<>();
		branch.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern statement) {
				Value predicate = statement.getPredicateVar().getValue();
				if (iri(expectedFirst).equals(predicate) || iri(otherPredicate).equals(predicate)) {
					statements.add(statement);
				}
			}
		});
		assertThat(statements).hasSize(2);
		assertThat(statements.getFirst().getPredicateVar().getValue())
				.as("the arm is planned using only the inputs admitted by its containing evaluator")
				.isEqualTo(iri(expectedFirst));
	}

	private static void assertEndpointLookupFirst(RecordingTripleSource source, String endpointPredicate,
			String independentPredicate) {
		List<StatementRequest> branchRequests = branchRequests(source, endpointPredicate, independentPredicate);
		assertThat(branchRequests.getFirst().predicate()).isEqualTo(iri(endpointPredicate));
		assertThat(branchRequests.getFirst().subject()).isEqualTo(iri("endValue"));
	}

	private static List<StatementRequest> branchRequests(RecordingTripleSource source, String firstPredicate,
			String secondPredicate) {
		List<StatementRequest> branchRequests = source.requests.stream()
				.filter(request -> iri(firstPredicate).equals(request.predicate())
						|| iri(secondPredicate).equals(request.predicate()))
				.toList();
		assertThat(branchRequests).isNotEmpty();
		return branchRequests;
	}

	private static QueryRoot parse(String query) {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		return expression instanceof QueryRoot root ? root : new QueryRoot(expression);
	}

	private static Union onlyUnion(TupleExpr expression) {
		List<Union> unions = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Union union) {
				unions.add(union);
				super.meet(union);
			}
		});
		assertThat(unions).hasSize(1);
		return unions.getFirst();
	}

	private static List<BindingSet> evaluate(TupleExpr expression, RecordingStrategy strategy) {
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> results = strategy.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (results.hasNext()) {
				rows.add(new QueryBindingSet(results.next()));
			}
		}
		return rows;
	}

	private static IRI iri(String localName) {
		return VF.createIRI("urn:" + localName);
	}

	private static Statement statement(String subject, String predicate, String object) {
		return VF.createStatement(iri(subject), iri(predicate), iri(object));
	}

	private static BindingSet row(String... namesAndValues) {
		MapBindingSet row = new MapBindingSet();
		for (int i = 0; i < namesAndValues.length; i += 2) {
			row.addBinding(namesAndValues[i], iri(namesAndValues[i + 1]));
		}
		return row;
	}

	private record StatementRequest(Resource subject, IRI predicate, Value object) {
	}

	private static final class RecordingTripleSource implements TripleSource {

		private final List<Statement> statements;
		private final List<StatementRequest> requests = new ArrayList<>();

		private RecordingTripleSource(List<Statement> statements) {
			this.statements = statements;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			requests.add(new StatementRequest(subject, predicate, object));
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subject == null || subject.equals(statement.getSubject()))
					.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
					.filter(statement -> object == null || object.equals(statement.getObject()))
					.filter(statement -> contexts == null || contexts.length == 0 || Arrays.stream(contexts)
							.anyMatch(context -> Objects.equals(context, statement.getContext())))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}

	private static final class RecordingStrategy extends DefaultEvaluationStrategy {

		private final Map<Union, List<BindingSet>> inputs = new IdentityHashMap<>();

		private RecordingStrategy(TripleSource tripleSource) {
			super(tripleSource, null);
		}

		@Override
		protected QueryEvaluationStep prepare(Union union, QueryEvaluationContext context) {
			QueryEvaluationStep delegate = super.prepare(union, context);
			List<BindingSet> incoming = new ArrayList<>();
			inputs.put(union, incoming);
			return bindings -> {
				incoming.add(new QueryBindingSet(bindings));
				return delegate.evaluate(bindings);
			};
		}
	}
